<template>
  <div class="min-h-screen px-4 py-8 sm:px-6 lg:px-8"><div class="mx-auto max-w-[1500px] space-y-6">
    <PageHeader :title="t('admin_billing.payments_title')" :description="t('admin_billing.payments_desc')" />
    <div class="rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-white/10 dark:bg-white/5">
      <form class="grid gap-3 border-b border-slate-200 p-4 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-6 dark:border-white/10" @submit.prevent="applyFilters">
        <input v-model.trim="filters.search" class="billing-input xl:col-span-2" :placeholder="t('admin_billing.search_payment')" />
        <input v-model.trim="filters.organization_id" class="billing-input" :placeholder="t('admin_billing.organization_id')" />
        <select v-model="filters.payment_type" class="billing-input"><option value="">{{ t('admin_billing.all_types') }}</option><option value="subscription_upgrade">{{ t('admin_billing.payment_type_subscription') }}</option><option value="token_topup">{{ t('admin_billing.payment_type_topup') }}</option></select>
        <select v-model="filters.plan_code" class="billing-input"><option value="">{{ t('admin_billing.all_plans') }}</option><option v-for="plan in plans" :key="plan.id" :value="plan.code">{{ plan.name }}</option></select>
        <select v-model="filters.billing_cycle" class="billing-input"><option value="">{{ t('admin_billing.all_cycles') }}</option><option value="monthly">{{ t('admin_billing.monthly') }}</option><option value="annual">{{ t('admin_billing.annual') }}</option></select>
        <select v-model="filters.status" class="billing-input"><option value="">{{ t('admin_billing.all_statuses') }}</option><option v-for="status in statuses" :key="status" :value="status">{{ statusLabel(status) }}</option></select>
        <input v-model="filters.date_from" type="date" class="billing-input" :title="t('admin_billing.from_date')" /><input v-model="filters.date_to" type="date" class="billing-input" :title="t('admin_billing.to_date')" />
        <select v-model="filters.month" class="billing-input"><option value="">{{ t('admin_billing.all_months') }}</option><option v-for="month in 12" :key="month" :value="month">{{ t('admin_billing.monthly') }} {{ month }}</option></select>
        <input v-model="filters.year" type="number" min="2000" max="2100" class="billing-input" :placeholder="t('admin_billing.year')" />
        <div class="flex gap-2"><button class="flex-1 rounded-xl bg-slate-900 px-4 py-2.5 text-sm font-bold text-white dark:bg-white dark:text-slate-900">{{ t('admin_billing.filter') }}</button><button type="button" class="rounded-xl border border-slate-200 px-3 dark:border-white/10" :title="t('admin_billing.filter_off')" @click="resetFilters"><span class="material-symbols-outlined">filter_alt_off</span></button></div>
      </form>
      <PageState :loading="loading" :error="error" :empty="!payments.length" :empty-text="t('admin_billing.no_data')" @retry="load">
        <div class="overflow-x-auto"><table class="min-w-[1000px] w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500 dark:bg-black/20 dark:text-slate-400"><tr><th class="p-4">{{ t('admin_billing.header_order_code') }}</th><th class="p-4">{{ t('admin_billing.header_user') }}</th><th class="p-4">{{ t('admin_billing.header_payment_organization') }}</th><th class="p-4">{{ t('admin_billing.header_payment_type_plan') }}</th><th class="p-4">{{ t('admin_billing.header_amount') }}</th><th class="p-4">{{ t('admin_billing.header_cycle') }}</th><th class="p-4">{{ t('admin_billing.header_status') }}</th><th class="p-4">{{ t('admin_billing.header_transaction_hash') }}</th><th class="p-4">{{ t('admin_billing.header_time') }}</th><th class="p-4">{{ t('admin_billing.header_paid') }}</th><th class="p-4 text-right">{{ t('admin_billing.header_actions') }}</th></tr></thead>
          <tbody class="divide-y divide-slate-100 dark:divide-white/5"><tr v-for="payment in payments" :key="payment.id"><td class="p-4 font-mono text-xs font-bold text-cyan-700 dark:text-cyan-300">{{ payment.order_code }}</td><td class="p-4"><p class="font-semibold dark:text-white">{{ payment.user?.name || '—' }}</p><p class="text-xs text-slate-500">{{ payment.user?.email || '—' }}</p></td><td class="p-4 font-semibold">{{ payment.organization?.name || '—' }}</td><td class="p-4"><p>{{ payment.payment_type === 'token_topup' ? t('admin_billing.payment_type_topup') : t('admin_billing.payment_type_subscription') }}</p><p class="text-xs text-slate-500">{{ payment.plan_snapshot?.name || payment.plan_snapshot?.code || (payment.token_amount_snapshot ? `${formatBillingNumber(payment.token_amount_snapshot)} token` : '—') }}</p></td><td class="p-4 font-bold">{{ formatBillingMoney(payment.amount_snapshot ?? payment.amount, payment.currency_snapshot || 'VND') }}</td><td class="p-4">{{ payment.billing_cycle_snapshot === 'monthly' ? t('admin_billing.monthly') : payment.billing_cycle_snapshot === 'annual' ? t('admin_billing.annual') : '—' }}</td><td class="p-4"><StatusBadge :status="payment.status" /></td><td class="p-4 max-w-48 truncate font-mono text-xs" :title="payment.transaction_hash || ''">{{ payment.transaction_hash || '—' }}</td><td class="p-4 whitespace-nowrap"><p>{{ formatBillingDate(payment.created_at, true) }}</p><p class="text-xs text-slate-500">{{ t('admin_billing.expired_prefix', { date: formatBillingDate(payment.expires_at, true) }) }}</p></td><td class="p-4 whitespace-nowrap">{{ payment.paid_at ? formatBillingDate(payment.paid_at, true) : t('admin_billing.not_paid') }}</td><td class="p-4"><div class="flex justify-end gap-2"><NuxtLink :to="`/admin/billing/payments/${payment.id}`" class="icon-button" :title="t('admin_billing.details')"><span class="material-symbols-outlined text-lg">visibility</span></NuxtLink><button v-if="payment.status === 'pending'" class="icon-button text-rose-600" :title="t('admin_billing.cancel_payment')" :disabled="actingId === payment.id" @click="openAction(payment, 'cancel')"><span class="material-symbols-outlined text-lg">cancel</span></button><button v-if="payment.status === 'pending'" class="icon-button text-amber-600" :title="t('admin_billing.expire_payment')" :disabled="actingId === payment.id" @click="openAction(payment, 'expire')"><span class="material-symbols-outlined text-lg">timer_off</span></button></div></td></tr></tbody>
        </table></div><Pagination :pagination="pagination" @change="changePage" />
      </PageState>
    </div>
    <ReasonModal v-model="actionOpen" :title="action === 'cancel' ? t('admin_billing.cancel_payment') : t('admin_billing.expire_payment')" :description="selected?.order_code || ''" :warning="t('admin_billing.payment_action_warning')" :action-label="action === 'cancel' ? t('admin_billing.action_confirm_cancel') : t('admin_billing.action_confirm_expire')" :danger="action === 'cancel'" :busy="Boolean(actingId)" :server-error="actionError" @submit="performAction" />
  </div></div>
</template>

<script setup lang="ts">
import type { AdminPayment, BillingPagination, BillingPlan } from '~/types/admin-billing'
import PageHeader from '~/components/admin/billing/PageHeader.vue'; import PageState from '~/components/admin/billing/PageState.vue'; import Pagination from '~/components/admin/billing/Pagination.vue'; import StatusBadge from '~/components/admin/billing/StatusBadge.vue'; import ReasonModal from '~/components/admin/billing/ReasonModal.vue'; import { formatBillingDate, formatBillingMoney, formatBillingNumber } from '~/utils/adminBilling'
definePageMeta({ layout: 'layout-admin' })
const { t } = useI18n()
const statusLabel = (status: string) => { const key = `admin_billing.status_${status}`; const translated = t(key); return translated === key ? status : translated }
const route = useRoute(); const api = useAdminBilling(); const toast = useToast(); const payments = ref<AdminPayment[]>([]); const plans = ref<BillingPlan[]>([]); const statuses = ['pending', 'success', 'completed', 'failed', 'expired', 'cancelled']; const pagination = ref<BillingPagination>({ current_page: 1, per_page: 20, total: 0, last_page: 1 }); const defaultFilters = () => ({ search: '', organization_id: '', payment_type: '', plan_code: '', billing_cycle: '', status: String(route.query.status || ''), date_from: '', date_to: '', month: '', year: '', page: 1, per_page: 20 }); const filters = reactive(defaultFilters()); const loading = ref(true); const error = ref(''); const actionOpen = ref(false); const action = ref<'cancel'|'expire'>('cancel'); const selected = ref<AdminPayment | null>(null); const actingId = ref<number | null>(null); const actionError = ref('')
const load = async () => { loading.value = true; error.value = ''; try { const response = await api.listPayments(filters); payments.value = response.data; pagination.value = response.pagination } catch (e) { error.value = getAdminBillingErrorMessage(e) } finally { loading.value = false } }
const loadPlans = async () => { try { const response = await api.listPlans({ per_page: 100 }); plans.value = response.data } catch {} }
const applyFilters = () => { filters.page = 1; load() }; const resetFilters = () => { Object.assign(filters, defaultFilters(), { status: '' }); load() }; const changePage = (page: number) => { filters.page = page; load() }; const openAction = (payment: AdminPayment, next: 'cancel'|'expire') => { selected.value = payment; action.value = next; actionError.value = ''; actionOpen.value = true }
const performAction = async (reason: string) => { if (!selected.value || actingId.value) return; actingId.value = selected.value.id; actionError.value = ''; try { if (action.value === 'cancel') await api.cancelPayment(selected.value.id, reason); else await api.expirePayment(selected.value.id, reason); toast.success(action.value === 'cancel' ? t('admin_billing.payment_cancelled') : t('admin_billing.payment_expired')); actionOpen.value = false; await load() } catch (e) { actionError.value = getAdminBillingErrorMessage(e); toast.error(actionError.value); if (e instanceof AdminBillingError && e.code === 'PAYMENT_ALREADY_PROCESSED') await load() } finally { actingId.value = null } }
onMounted(() => { load(); loadPlans() })
</script>
<style scoped>.billing-input{ @apply w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm outline-none focus:border-cyan-500 dark:border-white/10 dark:bg-black/20 dark:text-white; }.icon-button{ @apply inline-flex rounded-lg border border-slate-200 p-2 hover:border-cyan-400 dark:border-white/10 disabled:opacity-40; }</style>
